export function getRtaSection(typeOrVal) {
  if (!typeOrVal) return RTA_ORGANIZATION_SECTIONS[1]; // fallback to COMBAT
  const s = String(typeOrVal).trim().toLowerCase();
  
  const byCode = RTA_ORGANIZATION_SECTIONS.find((sec) => sec.code.toLowerCase() === s);
  if (byCode) return byCode;

  if (s.includes('บัญชาการ') || s.includes('headquarters') || s.includes('command')) {
    return RTA_ORGANIZATION_SECTIONS[0]; // COMMAND
  }
  if (s.includes('ช่วยรบ') || s.includes('สนับสนุนการช่วยรบ') || s.includes('service') || s.includes('ยุทธบริการ') || s.includes('บชร') || s.includes('พธ.') || s.includes('สรรพาวุธ') || s.includes('แพทย์') || s.includes('ขนส่ง')) {
    return RTA_ORGANIZATION_SECTIONS[3]; // COMBAT_SERVICE_SUPPORT
  }
  if (s.includes('สนับสนุน') || s.includes('combat support') || s.includes('support') || s.includes('ปืนใหญ่') || s.includes('สื่อสาร') || s.includes('ช่าง') || s.includes('ปตอ.') || s.includes('การบิน')) {
    return RTA_ORGANIZATION_SECTIONS[2]; // COMBAT_SUPPORT
  }
  if (s.includes('กำลังรบ') || s.includes('combat') || s.includes('รบหลัก') || s.includes('ทหารราบ') || s.includes('ทหารม้า') || s.includes('รบพิเศษ') || s === 'regular' || s === 'division' || s === 'special') {
    return RTA_ORGANIZATION_SECTIONS[1]; // COMBAT
  }
  if (s.includes('ภูมิภาค') || s.includes('territorial') || s.includes('regional') || s.includes('ทภ.') || s.includes('กองทัพภาค') || s.includes('มณฑล') || s.includes('มทบ') || s === 'army_region') {
    return RTA_ORGANIZATION_SECTIONS[4]; // REGIONAL
  }
  if (s.includes('ศึกษา') || s.includes('education') || s.includes('training') || s.includes('ยศ.ทบ.') || s.includes('จปร') || s.includes('รร.')) {
    return RTA_ORGANIZATION_SECTIONS[5]; // EDUCATION_TRAINING
  }
  if (s.includes('พัฒนา') || s.includes('development') || s.includes('พล.พัฒนา') || s.includes('ช.พัฒนา')) {
    return RTA_ORGANIZATION_SECTIONS[6]; // NATIONAL_DEVELOPMENT
  }
  
  return RTA_ORGANIZATION_SECTIONS.find((sec) => sec.code === 'OTHER') || RTA_ORGANIZATION_SECTIONS[7];
}

